<description>
Part of #36692: This replaces the resize-then-assign construction of transaction inputs and outputs in the `make_tx` helper of `miniminer_tests` with `CTxIn` and `CTxOut` ctor calls.

This change is test-only and does not change the constructed transactions
</description>

<commits>
4cddbcf534 test: construct miniminer_tests inputs/outputs declaratively

Replace the resize-then-assign construction of the inputs and outputs
in the make_tx helper with CTxIn and CTxOut constructor calls.

The constructed transactions are unchanged.
</commits>

<files>
src/test/miniminer_tests.cpp  +6/-11

(test/bench/ci lines: 17)
</files>

<patch>
diff --git a/src/test/miniminer_tests.cpp b/src/test/miniminer_tests.cpp
index c5048ceb45..8d6888d85c 100644
--- a/src/test/miniminer_tests.cpp
+++ b/src/test/miniminer_tests.cpp
@@ -22,18 +22,13 @@ const CAmount high_fee{CENT/10}; // 100_000 ṩ

 static inline CTransactionRef make_tx(const std::vector<COutPoint>& inputs, size_t num_outputs)
 {
-    CMutableTransaction tx = CMutableTransaction();
-    tx.vin.resize(inputs.size());
-    tx.vout.resize(num_outputs);
-    for (size_t i = 0; i < inputs.size(); ++i) {
-        tx.vin[i].prevout = inputs[i];
-    }
-    for (size_t i = 0; i < num_outputs; ++i) {
-        tx.vout[i].scriptPubKey = CScript() << OP_11 << OP_EQUAL;
-        // The actual input and output values of these transactions don't really
-        // matter, since all accounting will use the entries' cached fees.
-        tx.vout[i].nValue = COIN;
+    CMutableTransaction tx;
+    for (const auto& input : inputs) {
+        tx.vin.emplace_back(input);
     }
+    // The actual input and output values of these transactions don't really
+    // matter, since all accounting will use the entries' cached fees.
+    tx.vout.assign(num_outputs, CTxOut{COIN, CScript{} << OP_11 << OP_EQUAL});
     return MakeTransactionRef(tx);
 }


</patch>
